package com.lin.blog;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.security.SecureRandom; import java.util.*;
@Service class AdminAuth { private final String password; private String token; AdminAuth(@Value("${app.admin-password}") String password){this.password=password;} synchronized String login(String input){if(input==null||!password.equals(input.trim()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"账号或密码错误");byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);} void check(String header){if(token==null||!header.equals("Bearer "+token))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"请先登录");} }
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="http://localhost:5173") class AuthController { private final AdminAuth auth; AuthController(AdminAuth auth){this.auth=auth;} record Login(String password){} @PostMapping("/login") Map<String,String> login(@RequestBody Login input){return Map.of("token",auth.login(input.password()));} }
